final class PostTests: XCTestCase {
    func testDecodeTextPost() throws {
        // Test with actual API response format (submolt included)
        let json = """
        {
            "id": "post_123",
            "title": "Hello World",
            "content": "This is my first post",
            "url": null,
            "author": {
                "id": "agent_1",
                "name": "TestBot"
            },
            "submolt": {
                "id": "submolt_1",
                "name": "general",
                "display_name": "General",
                "is_subscribed": true
            },
            "upvotes": 50,
            "downvotes": 8,
            "comment_count": 5,
            "created_at": "2026-01-30T12:00:00Z"
        }
        """.data(using: .utf8)!

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let post = try decoder.decode(Post.self, from: json)

        XCTAssertEqual(post.id, "post_123")
        XCTAssertEqual(post.title, "Hello World")
        XCTAssertEqual(post.content, "This is my first post")
        XCTAssertNil(post.url)
        XCTAssertEqual(post.author?.name, "TestBot")
        XCTAssertEqual(post.submolt?.name, "general")
        XCTAssertEqual(post.submolt?.displayName, "General")
        XCTAssertEqual(post.upvotes, 50)
        XCTAssertEqual(post.downvotes, 8)
        XCTAssertEqual(post.voteCount, 42) // 50 - 8
        XCTAssertEqual(post.commentCount, 5)
        XCTAssertFalse(post.isLinkPost)
    }

    func testDecodeLinkPost() throws {
        let json = """
        {
            "id": "post_456",
            "title": "Check this out",
            "content": null,
            "url": "https://example.com/article",
            "author": {"id": "agent_2", "name": "LinkBot"},
            "submolt": {"id": "submolt_2", "name": "links"},
            "upvotes": 10,
            "downvotes": 0,
            "comment_count": 2,
            "created_at": "2026-01-30T10:00:00Z"
        }
        """.data(using: .utf8)!

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let post = try decoder.decode(Post.self, from: json)

        XCTAssertEqual(post.url?.absoluteString, "https://example.com/article")
        XCTAssertNil(post.content)
        XCTAssertTrue(post.isLinkPost)
        XCTAssertEqual(post.voteCount, 10)
    }

    func testDecodeRealAPIResponse() throws {
        // Test with actual response from Moltbook API
        let json = """
        {
            "id": "cbd6474f-8478-4894-95f1-7b104a73bcd5",
            "title": "Test Post Title",
            "content": "Post content here",
            "url": null,
            "upvotes": 22178,
            "downvotes": 5,
            "comment_count": 1932,
            "created_at": "2026-01-30T05:39:05.821605+00:00",
            "author": {
                "id": "7e33c519-8140-4370-b274-b4a9db16f766",
                "name": "eudaemon_0"
            },
            "submolt": {
                "id": "29beb7ee-ca7d-4290-9c2f-09926264866f",
                "name": "general",
                "display_name": "General"
            }
        }
        """.data(using: .utf8)!

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let post = try decoder.decode(Post.self, from: json)

        XCTAssertEqual(post.id, "cbd6474f-8478-4894-95f1-7b104a73bcd5")
        XCTAssertEqual(post.upvotes, 22178)
        XCTAssertEqual(post.downvotes, 5)
        XCTAssertEqual(post.voteCount, 22173)
        XCTAssertEqual(post.author?.name, "eudaemon_0")
        XCTAssertEqual(post.submolt?.title, "General")
    }

    func testDecodePostWithoutSubmolt() throws {
        // Posts in submolt detail responses don't include submolt field
        let json = """
        {
            "id": "post_789",
            "title": "Post in submolt",
            "content": "No submolt field here",
            "url": null,
            "author": {"id": "agent_3", "name": "Agent3"},
            "upvotes": 5,
            "downvotes": 1,
            "comment_count": 0,
            "created_at": "2026-01-30T12:00:00Z"
        }
        """.data(using: .utf8)!

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let post = try decoder.decode(Post.self, from: json)

        XCTAssertEqual(post.id, "post_789")
        XCTAssertNil(post.submolt)
        XCTAssertEqual(post.author?.name, "Agent3")
    }
}

import SwiftUI

public struct ComposePostView: View {
    @Environment(AppState.self) private var appState
    @Environment(\.dismiss) private var dismiss

    @State private var title = ""
    @State private var content = ""
    @State private var url = ""
    @State private var isLinkPost = false
    @State private var selectedSubmolt: Submolt?
    @State private var submolts: [Submolt] = []
    @State private var isLoading = false
    @State private var isSubmitting = false
    @State private var error: String?

    public init() {}

    private var canSubmit: Bool {
        !title.isEmpty && selectedSubmolt != nil && !isSubmitting
    }

    public var body: some View {
        NavigationStack {
            Form {
                Section("Post Type") {
                    Picker("Type", selection: $isLinkPost) {
                        Text("Text").tag(false)
                        Text("Link").tag(true)
                    }
                    .pickerStyle(.segmented)
                }

                Section("Content") {
                    TextField("Title", text: $title)

                    if isLinkPost {
                        TextField("URL", text: $url)
                            #if os(iOS)
                            .keyboardType(.URL)
                            .textInputAutocapitalization(.never)
                            #endif
                    } else {
                        TextField("Body (optional)", text: $content, axis: .vertical)
                            .lineLimit(5...10)
                    }
                }

                Section("Community") {
                    if isLoading {
                        ProgressView()
                    } else {
                        Picker("Submolt", selection: $selectedSubmolt) {
                            Text("Select a community").tag(nil as Submolt?)
                            ForEach(submolts) { submolt in
                                Text(submolt.name).tag(submolt as Submolt?)
                            }
                        }
                    }
                }

                if let error = error {
                    Section {
                        Text(error)
                            .foregroundStyle(.red)
                    }
                }
            }
            .navigationTitle("New Post")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Post") {
                        Task { await submit() }
                    }
                    .disabled(!canSubmit)
                }
            }
            .task {
                await loadSubmolts()
            }
        }
    }

    private func loadSubmolts() async {
        isLoading = true
        do {
            let response = try await appState.api.getSubmolts()
            submolts = response.submolts
        } catch {
            self.error = "Failed to load communities"
        }
        isLoading = false
    }

    private func submit() async {
        guard let submolt = selectedSubmolt else { return }

        isSubmitting = true
        error = nil

        do {
            _ = try await appState.api.createPost(
                title: title,
                content: isLinkPost ? nil : (content.isEmpty ? nil : content),
                url: isLinkPost ? url : nil,
                submolt: submolt.name
            )
            dismiss()
        } catch let apiError as APIError {
            if apiError.error == "rate_limited", let minutes = apiError.retryAfterMinutes {
                error = "You can post again in \(minutes) minutes"
            } else {
                error = apiError.message ?? apiError.error
            }
        } catch let decodingError as DecodingError {
            self.error = "Decode error: \(decodingError.localizedDescription)"
        } catch {
            self.error = "Failed to create post: \(error.localizedDescription)"
        }

        isSubmitting = false
    }
}

import SwiftUI

public struct ComposeCommentView: View {
    @Environment(AppState.self) private var appState
    @Environment(\.dismiss) private var dismiss

    public let postId: String
    public var parentId: String?

    @State private var content = ""
    @State private var isSubmitting = false
    @State private var error: String?

    public init(postId: String, parentId: String? = nil) {
        self.postId = postId
        self.parentId = parentId
    }

    private var canSubmit: Bool {
        !content.isEmpty && !isSubmitting
    }

    public var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField("Write a comment...", text: $content, axis: .vertical)
                        .lineLimit(3...10)
                }

                if let error = error {
                    Section {
                        Text(error)
                            .foregroundStyle(.red)
                    }
                }
            }
            .navigationTitle(parentId != nil ? "Reply" : "Comment")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Post") {
                        Task { await submit() }
                    }
                    .disabled(!canSubmit)
                }
            }
        }
    }

    private func submit() async {
        isSubmitting = true
        error = nil

        do {
            _ = try await appState.api.createComment(postId: postId, content: content, parentId: parentId)
            dismiss()
        } catch let apiError as APIError {
            if apiError.error == "rate_limited" {
                error = "Comment rate limit reached. Please wait."
            } else {
                error = apiError.message ?? apiError.error
            }
        } catch {
            self.error = "Failed to post comment"
        }

        isSubmitting = false
    }
}

import Foundation

public struct Submolt: Codable, Identifiable, Equatable, Hashable {
    private var _id: String?
    public let name: String
    public var displayName: String?
    public var description: String?
    public var subscriberCount: Int?
    public var isSubscribed: Bool

    // Identifiable conformance - use id if available, fall back to name
    public var id: String { _id ?? name }

    enum CodingKeys: String, CodingKey {
        case _id = "id"
        case name, description
        case displayName = "display_name"
        case subscriberCount = "subscriber_count"
        case isSubscribed = "is_subscribed"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        _id = try container.decodeIfPresent(String.self, forKey: ._id)
        name = try container.decode(String.self, forKey: .name)
        displayName = try container.decodeIfPresent(String.self, forKey: .displayName)
        description = try container.decodeIfPresent(String.self, forKey: .description)
        subscriberCount = try container.decodeIfPresent(Int.self, forKey: .subscriberCount)
        isSubscribed = try container.decodeIfPresent(Bool.self, forKey: .isSubscribed) ?? false
    }

    /// Returns display name if available, otherwise the raw name
    public var title: String {
        displayName ?? name
    }
}

