import SwiftUI
import os.log

private let logger = Logger(subsystem: "com.moltipass", category: "feed")

@MainActor
@Observable
public class FeedViewModel {
    public var posts: [Post] = []
    public var isLoading = false
    public var error: String?
    public var selectedSort: FeedSort = .hot
    private var nextCursor: String?

    private let api: MoltbookAPI

    public init(api: MoltbookAPI) {
        self.api = api
    }

    public func loadFeed(refresh: Bool = false) async {
        if refresh {
            nextCursor = nil
        }

        guard !isLoading else { return }
        isLoading = true
        error = nil

        logger.info("Loading feed, sort: \(self.selectedSort.rawValue), refresh: \(refresh)")

        do {
            let response = try await api.getFeed(sort: selectedSort, cursor: refresh ? nil : nextCursor)
            logger.info("Loaded \(response.posts.count) posts")
            if refresh {
                posts = response.posts
            } else {
                posts.append(contentsOf: response.posts)
            }
            nextCursor = response.nextCursor
        } catch let apiError as APIError {
            logger.error("Feed load API error: \(apiError.error)")
            error = apiError.message ?? apiError.error
        } catch {
            logger.error("Feed load error: \(error)")
            self.error = "Failed to load feed: \(error.localizedDescription)"
        }

        isLoading = false
    }

    public func vote(post: Post, direction: Int) async {
        guard let index = posts.firstIndex(where: { $0.id == post.id }) else { return }

        let oldUpvotes = posts[index].upvotes
        let oldDownvotes = posts[index].downvotes

        // Optimistic update
        if direction > 0 {
            posts[index].upvotes += 1
        } else if direction < 0 {
            posts[index].downvotes += 1
        }

        do {
            try await api.votePost(id: post.id, direction: direction)
            logger.info("Vote succeeded for post \(post.id)")
        } catch {
            logger.error("Vote failed: \(error)")
            // Revert on error
            posts[index].upvotes = oldUpvotes
            posts[index].downvotes = oldDownvotes
        }
    }
}

import SwiftUI

public struct SearchView: View {
    @Environment(AppState.self) private var appState
    @State private var query = ""
    @State private var scope: SearchScope = .posts
    @State private var posts: [Post] = []
    @State private var agents: [Agent] = []
    @State private var submolts: [Submolt] = []
    @State private var isSearching = false

    public init() {}

    public var body: some View {
        NavigationStack {
            List {
                if !query.isEmpty {
                    switch scope {
                    case .posts:
                        ForEach(posts) { post in
                            NavigationLink(value: post) {
                                PostCellView(post: post)
                            }
                        }
                    case .agents:
                        ForEach(agents) { agent in
                            NavigationLink(value: agent) {
                                AgentRow(agent: agent)
                            }
                        }
                    case .submolts:
                        ForEach(submolts) { submolt in
                            NavigationLink(value: submolt) {
                                SubmoltRow(submolt: submolt)
                            }
                        }
                    }
                }
            }
            .navigationTitle("Search")
            .searchable(text: $query, prompt: "Search Moltbook")
            .searchScopes($scope) {
                Text("Posts").tag(SearchScope.posts)
                Text("Users").tag(SearchScope.agents)
                Text("Communities").tag(SearchScope.submolts)
            }
            .onChange(of: query) {
                Task { await search() }
            }
            .onChange(of: scope) {
                Task { await search() }
            }
            .navigationDestination(for: Post.self) { post in
                PostDetailView(post: post)
            }
            .navigationDestination(for: Submolt.self) { submolt in
                SubmoltDetailView(submolt: submolt)
            }
            .navigationDestination(for: Agent.self) { agent in
                UserProfileView(agent: agent)
            }
        }
    }

    private func search() async {
        guard !query.isEmpty else {
            posts = []
            agents = []
            submolts = []
            return
        }

        isSearching = true
        do {
            let response = try await appState.api.search(query: query, scope: scope)
            posts = response.posts ?? []
            agents = response.agents ?? []
            submolts = response.submolts ?? []
        } catch {
            // Handle error
        }
        isSearching = false
    }
}

